"""Naive independent reference model of the replay contract (for fuzzing)."""
import sys, struct
sys.path[:0]=['/opt/emicro-deps','/workspace/project']
from ebpf.create_dfa import create, registry_columns
D=4294967295
W=struct.Struct('>4sIIIII')

class Ref:
    def __init__(self, services, limits):
        self.cols,self.colmap=registry_columns(services)
        self.labels={s['name']:s['label'] for s in services}
        self.limits=limits
        self.images={}      # epoch -> (accept, rows)
        self.active=None
        self.stage_hwm=0
        self.units={}       # (ns,pid) -> dict
        self.genhwm={}
        self.conns={}
        self.connhwm={}
        self.files={}
        self.filehwm={}

    # ---- derived counters (recomputed, never incremental) ----
    def contexts(self):
        return sum(len(u['ctx']) for u in self.units.values())
    def packets(self):
        return sum(len(c['pk']) for c in self.conns.values())
    def nfiles(self):
        return len(self.files)
    def refs(self, epoch):
        n=0
        for u in self.units.values():
            for e,s in u['ctx'].values():
                if e==epoch: n+=1
        for c in self.conns.values():
            for p in c['pk'].values():
                if p['epoch']==epoch: n+=1
        for f in self.files.values():
            if f['epoch']==epoch: n+=1
        return n
    def cells(self, epoch):
        acc,rows=self.images[epoch]
        return sum(1 for r in rows for t in r if t!=D)
    def step(self, epoch, state, col):
        if state==D: return D
        return self.images[epoch][1][state][col]

    def unit(self, u):
        x=self.units.get((u[0],u[1]))
        if x is None or x['gen']!=u[2]: return None
        return x

    def event(self, e):
        op=e['op']
        if op=='stage':
            ep=e['epoch']
            if ep<=self.stage_hwm: return {'error':'rejected'}
            if len(self.images)+1>self.limits['images']: return {'error':'rejected'}
            try:
                img=create(e['policy'], self.cols, self.colmap)
            except Exception:
                return {'error':'rejected'}
            if len(img.rows)>8192: return {'error':'rejected'}
            total=sum(self.cells(x) for x in self.images)+img.cells
            if total>self.limits['cells']: return {'error':'rejected'}
            self.images[ep]=(list(img.accept),[list(r) for r in img.rows])
            self.stage_hwm=ep
            return {'ok':True,'epoch':ep,'image':{'accept':list(img.accept),'rows':[list(r) for r in img.rows]}}
        if op=='commit':
            if e['epoch'] not in self.images: return {'error':'rejected'}
            self.active=e['epoch']; return {'ok':True}
        if op=='retire':
            ep=e['epoch']
            if ep not in self.images or self.active==ep or self.refs(ep)!=0: return {'error':'rejected'}
            del self.images[ep]; return {'ok':True}
        if op=='spawn':
            u=e['unit']; k=(u[0],u[1])
            if k in self.units: return {'error':'rejected'}
            if u[2]<=self.genhwm.get(k,0): return {'error':'rejected'}
            if len(self.units)+1>self.limits['units']: return {'error':'rejected'}
            if e['service'] not in self.colmap: return {'error':'rejected'}
            self.units[k]={'gen':u[2],'service':e['service'],'col':self.colmap[e['service']],'mark':0,'ctx':{}}
            self.genhwm[k]=u[2]
            return {'ok':True}
        if op=='clone':
            p=self.unit(e['parent'])
            if p is None: return {'error':'rejected'}
            u=e['child']; k=(u[0],u[1])
            if k in self.units: return {'error':'rejected'}
            if u[2]<=self.genhwm.get(k,0): return {'error':'rejected'}
            if len(self.units)+1>self.limits['units']: return {'error':'rejected'}
            if self.contexts()+len(p['ctx'])>self.limits['contexts']: return {'error':'rejected'}
            self.units[k]={'gen':u[2],'service':p['service'],'col':p['col'],'mark':p['mark'],'ctx':dict(p['ctx'])}
            self.genhwm[k]=u[2]
            return {'ok':True}
        if op=='exit':
            u=e['unit']; k=(u[0],u[1])
            x=self.units.get(k)
            if x is None or x['gen']!=u[2]: return {'error':'rejected'}
            del self.units[k]; return {'ok':True}
        if op=='begin':
            x=self.unit(e['unit'])
            if x is None: return {'error':'rejected'}
            rid=e['rid']
            if rid<=x['mark']: return {'error':'rejected'}
            if self.active is None: return {'error':'rejected'}
            if self.contexts()+1>self.limits['contexts']: return {'error':'rejected'}
            st=self.step(self.active,0,x['col'])
            x['ctx'][rid]=(self.active,st); x['mark']=rid
            return {'ok':True,'epoch':self.active,'state':st}
        if op=='finish':
            x=self.unit(e['unit'])
            if x is None: return {'error':'rejected'}
            c=x['ctx'].get(e['rid'])
            if c is None: return {'error':'rejected'}
            del x['ctx'][e['rid']]
            ep,st=c
            return {'ok':True,'allow': (st!=D and self.images[ep][0][st])}
        if op=='open':
            c=e['connection']; cid=c[0]
            if cid in self.conns: return {'error':'rejected'}
            if c[1]<=self.connhwm.get(cid,0): return {'error':'rejected'}
            if len(self.conns)+1>self.limits['connections']: return {'error':'rejected'}
            self.conns[cid]={'gen':c[1],'mark':0,'pk':{}}
            self.connhwm[cid]=c[1]
            return {'ok':True}
        if op=='close':
            c=e['connection']
            cn=self.conns.get(c[0])
            if cn is None or cn['gen']!=c[1]: return {'error':'rejected'}
            del self.conns[c[0]]; return {'ok':True}
        if op=='send':
            x=self.unit(e['unit'])
            if x is None: return {'error':'rejected'}
            ctx=x['ctx'].get(e['rid'])
            if ctx is None: return {'error':'rejected'}
            c=e['connection']; cn=self.conns.get(c[0])
            if cn is None or cn['gen']!=c[1]: return {'error':'rejected'}
            s=e['stream']
            if s<=cn['mark']: return {'error':'rejected'}
            dest=e['destination']
            if dest not in self.labels: return {'error':'rejected'}
            if self.packets()+1>self.limits['packets']: return {'error':'rejected'}
            ep,st=ctx
            hx=W.pack(b'EMC4',ep,st,self.labels[dest],s,cn['gen']).hex()
            cn['pk'][s]={'epoch':ep,'state':st,'dest':dest,'hex':hx,'receipt':None}
            cn['mark']=s
            return {'ok':True,'wire':hx}
        if op=='recv':
            c=e['connection']; cn=self.conns.get(c[0])
            if cn is None or cn['gen']!=c[1]: return {'error':'rejected'}
            pk=cn['pk'].get(e['stream'])
            if pk is None: return {'error':'rejected'}
            u=e['unit']; x=self.units.get((u[0],u[1]))
            if x is None or x['gen']!=u[2]: return {'error':'rejected'}
            if x['service']!=pk['dest']: return {'error':'rejected'}
            w=e['wire']
            if w is not None and (len(w)!=48 or w.lower()!=pk['hex']): return {'error':'rejected'}
            rid=e['rid']
            if pk['receipt'] is not None:
                if pk['receipt']!=(u[0],u[1],u[2],rid): return {'error':'rejected'}
                ctx=x['ctx'].get(rid)
                if ctx is None: return {'error':'rejected'}
                return {'ok':True,'epoch':ctx[0],'state':ctx[1]}
            if rid<=x['mark']: return {'error':'rejected'}
            if self.contexts()+1>self.limits['contexts']: return {'error':'rejected'}
            st=self.step(pk['epoch'],pk['state'],x['col'])
            x['ctx'][rid]=(pk['epoch'],st); x['mark']=rid
            pk['receipt']=(u[0],u[1],u[2],rid)
            return {'ok':True,'epoch':pk['epoch'],'state':st}
        if op=='store':
            x=self.unit(e['unit'])
            if x is None: return {'error':'rejected'}
            ctx=x['ctx'].get(e['rid'])
            if ctx is None: return {'error':'rejected'}
            f=e['file']; cur=self.files.get(f[0])
            if cur is None:
                if f[1]<=self.filehwm.get(f[0],0): return {'error':'rejected'}
                if self.nfiles()+1>self.limits['files']: return {'error':'rejected'}
                self.files[f[0]]={'gen':f[1],'epoch':ctx[0],'state':ctx[1]}
                self.filehwm[f[0]]=f[1]
                return {'ok':True}
            if cur['gen']!=f[1]: return {'error':'rejected'}
            cur['epoch'],cur['state']=ctx
            return {'ok':True}
        if op=='load':
            f=e['file']; cur=self.files.get(f[0])
            if cur is None or cur['gen']!=f[1]: return {'error':'rejected'}
            x=self.unit(e['unit'])
            if x is None: return {'error':'rejected'}
            rid=e['rid']
            if rid<=x['mark']: return {'error':'rejected'}
            if self.contexts()+1>self.limits['contexts']: return {'error':'rejected'}
            st=self.step(cur['epoch'],cur['state'],x['col'])
            x['ctx'][rid]=(cur['epoch'],st); x['mark']=rid
            return {'ok':True,'epoch':cur['epoch'],'state':st}
        if op=='unlink':
            f=e['file']; cur=self.files.get(f[0])
            if cur is None or cur['gen']!=f[1]: return {'error':'rejected'}
            del self.files[f[0]]; return {'ok':True}
        if op=='inspect':
            return {'ok':True,'active':self.active,
                    'images':[[ep,len(self.images[ep][0]),self.cells(ep),self.refs(ep)] for ep in sorted(self.images)],
                    'units':len(self.units),'contexts':self.contexts(),'connections':len(self.conns),
                    'packets':self.packets(),'files':self.nfiles()}
        return {'error':'rejected'}
