"""Differential fuzz: agent vs naive reference model."""
import json, random, sys
sys.path[:0]=['/workspace/tmp/tests','/opt/emicro-deps','/workspace/project']
from harness import call
from ref import Ref

POLICIES=[
 'match(A,B) allow;',
 'contains() allow;',
 'match(A) allow;',
 'startswith(A) allow; match(A,B) drop;',
 'contains(A,B) allow;',
 'endswith(B) allow;',
 '(match(A) or match(B)) allow;',
 'not(match(A)) allow; match(B) drop;',
 'match(A,B) allow; match(A,B,A) drop;',
 'contains(A) allow; contains(A,A) drop;',
 'match() allow;',
 '',
 'match(Z) allow;',                    # unregistered -> rejected stage
 'match(A) allow;;',                   # syntax -> rejected stage
]

def gen(rng, nevents):
    services=[]
    labels=rng.sample(range(1,4294967294),3)
    for n,l in zip(['A','B','C'],labels): services.append({'name':n,'label':l})
    lim={'images':rng.choice([1,2,3,16]),'cells':rng.choice([4,16,64,262144]),
         'units':rng.choice([1,2,4,1024]),'contexts':rng.choice([1,2,3,8,32768]),
         'connections':rng.choice([1,2,4096]),'packets':rng.choice([1,2,3,32768]),
         'files':rng.choice([1,2,8192])}
    events=[]
    epochs=[]
    for i in range(nevents):
        r=rng.random()
        unit=[rng.randint(0,1),rng.randint(1,3),rng.randint(1,3)]
        rid=rng.randint(1,4)
        conn=[rng.randint(1,2),rng.randint(1,2)]
        stream=rng.randint(1,3)
        file=[rng.randint(1,2),rng.randint(1,2)]
        if r<0.10:
            ep=rng.choice([1,2,3,4,5])
            events.append({'op':'stage','epoch':ep,'policy':rng.choice(POLICIES)}); epochs.append(ep)
        elif r<0.16: events.append({'op':'commit','epoch':rng.choice([1,2,3,4,5])})
        elif r<0.20: events.append({'op':'retire','epoch':rng.choice([1,2,3,4,5])})
        elif r<0.28: events.append({'op':'spawn','unit':unit,'service':rng.choice(['A','B','C','Z'])})
        elif r<0.34: events.append({'op':'clone','parent':unit,'child':[rng.randint(0,1),rng.randint(1,3),rng.randint(1,3)]})
        elif r<0.38: events.append({'op':'exit','unit':unit})
        elif r<0.48: events.append({'op':'begin','unit':unit,'rid':rid})
        elif r<0.55: events.append({'op':'finish','unit':unit,'rid':rid})
        elif r<0.60: events.append({'op':'open','connection':conn})
        elif r<0.63: events.append({'op':'close','connection':conn})
        elif r<0.72: events.append({'op':'send','unit':unit,'rid':rid,'connection':conn,'stream':stream,'destination':rng.choice(['A','B','C','Z'])})
        elif r<0.82:
            w=rng.random()
            wire=None if w<0.6 else ('0'*48 if w<0.7 else None)
            events.append({'op':'recv','unit':unit,'rid':rid,'connection':conn,'stream':stream,'wire':wire})
        elif r<0.88: events.append({'op':'store','unit':unit,'rid':rid,'file':file})
        elif r<0.93: events.append({'op':'load','file':file,'unit':unit,'rid':rid})
        elif r<0.95: events.append({'op':'unlink','file':file})
        else: events.append({'op':'inspect'})
    return {'services':services,'limits':lim,'events':events}

def main():
    seed=int(sys.argv[1]); rounds=int(sys.argv[2]); nevents=int(sys.argv[3]) if len(sys.argv)>3 else 60
    rng=random.Random(seed)
    bad=0
    for r in range(rounds):
        j=gen(rng,nevents)
        ref=Ref(j['services'],j['limits'])
        want=[ref.event(e) for e in j['events']]
        out,_=call(json.dumps({'jobs':[j]},separators=(',',':')))
        got=out['results'][0]
        if 'error' in got:
            print('JOB INVALID unexpectedly', json.dumps(got)); bad+=1; break
        got=got['events']
        if got!=want:
            bad+=1
            for i,(a,b) in enumerate(zip(got,want)):
                if a!=b:
                    print('seed',seed,'round',r,'diff at',i)
                    print('  event',json.dumps(j['events'][i]))
                    print('  got ',json.dumps(a)[:400])
                    print('  want',json.dumps(b)[:400])
                    print('  limits',j['limits'])
                    break
            if bad>=3: break
    print('fuzz_rt seed',seed,'rounds',rounds,'bad',bad)
main()
